import (
    "fmt"
    "sync/atomic"
)

type atomicQueue struct {
    buf []int
    len uint64
    mu  sync.Mutex
}

func (q *atomicQueue) Push(v int) {
    q.mu.Lock()
    q.buf = append(q.buf, v)
    q.len.Add(1)
    q.mu.Unlock()
}

func (q *atomicQueue) Pop() int {
    q.mu.Lock()
    v := q.buf[0]
    q.buf = q.buf[1:]
