    var wg sync.WaitGroup
    for i := 0; i < 10; i++ {
        wg.Add(1)
        go func(id int) {
            defer wg.Done()
            worker(id, q)
        }(i)
    }
    wg.Wait()
    for i := 0; i < int(q.len); i++ {
        fmt.Println(q.Pop())
    }
}
```

In this version, we use a `sync/atomic`-based queue to atomically push and pop elements. This ensures that the append operation is atomic.

