using namespace std;

typedef long long ll;

void solve() {
    ll a, b, c;
    cin >> a >> b >> c;
    vector<ll> ans;
    for (ll k = 2; k <= 1000000009; k++) {
        ll x = a % k, y = b % k, z = c % k;
        if ((x + y) % k == z) {
            ans.push_back(k);
        }
    }
    sort(ans.begin(), ans.end());
    if (ans.size() == 0) {
        cout << 0 << endl;
    } else if (ans.size() == 1) {
        cout << 1 << endl;
    } else if (ans.size() > 1 && ans[0] == ans[1]) {
        cout << 2 << endl;
    } else {
        cout << -1 << endl;
    }
}

int main() {
    int T;
    cin >> T;
    while (T--) {
        solve();
    }
    return 0;
}
