            int x = a % k, y = b % k, z = c % k;
            if ((x + y) % k == z) {
                ans++;
            }
        }
        if (ans == 0) {
            cout << 0 << endl;
        } else if (ans == 1) {
            cout << 1 << endl;
        } else if (ans == 2) {
            cout << 2 << endl;
        } else if (ans >= 3) {
            cout << -1 << endl;
        }
    }
