#include <bits/stdc++.h>
using namespace std;

void solve() {
    int n;
    string s;
    cin >> n >> s;

    int total_pairs = n / 2;
    int pairs = 0;
    int min_cost = INT_MAX;

    for (int i = 0; i < total_pairs; i++) {
        if (s[2 * i] == ')') {
            if (i - pairs >= 0) {
                int cost = (total_pairs - i - pairs) + (i - pairs);
                min_cost = min(min_cost, cost);
            }
        } else {
            pairs++;
        }
    }

    for (int i = 0; i < total_pairs; i++) {
        if (s[2 * i] == '(') {
            if (total_pairs - i - pairs >= i + 1) {
                int cost = (total_pairs - i - 1 - pairs) + (i + 1 - pairs);
                min_cost = min(min_cost, cost);
            }
        } else {
            pairs++;
        }
    }

    cout << min_cost << endl;
}

int main() {
    int t;
    cin >> t;
    while (t--) {
        solve();
    }
    return 0;
}
